mapper.select:
SELECT 
FROM shared_transaction t
LEFT JOIN users u ON u.id = t.author_id
WHERE t.calendar_id = #{calendarId}
  AND YEAR(t.transaction_date) = #{year}
  AND MONTH(t.transaction_date) = #{month}
ORDER BY t.transaction_date, t.sort_order IS NULL, t.sort_order, t.id

SELECT COUNT(*)
FROM shared_transaction
WHERE recurring_origin_id = #{originId}
  AND YEAR(transaction_date) = #{year}
  AND MONTH(transaction_date) = #{month}

SELECT 
FROM shared_event e
LEFT JOIN users u ON u.id = e.author_id
WHERE e.calendar_id = #{calendarId}
  AND e.start_date <= #{monthEnd}
  AND e.end_date >= #{monthStart}
ORDER BY e.start_date, e.event_time IS NULL, e.event_time, e.id
